import React, { useEffect, useState } from 'react';
import IncidentTable from '../components/IncidentTable/IncidentTable';
import { useIncidents } from '../hooks/useSupplyChain';
import './Incidents.css';

const SEVERITY_OPTIONS = ['', 'low', 'medium', 'high'];
const STATUS_OPTIONS = ['', 'delayed', 'in_transit', 'delivered', 'pending'];

export default function Incidents() {
  const { loading, error, data, load } = useIncidents();
  const [filters, setFilters] = useState({ supplier_id: '', warehouse_location: '', shipment_status: '', severity: '' });
  const [limit, setLimit] = useState(50);

  useEffect(() => {
    const params = { limit, ...Object.fromEntries(Object.entries(filters).filter(([, v]) => v)) };
    load(params);
  }, []);

  const handleSearch = () => {
    const params = { limit, ...Object.fromEntries(Object.entries(filters).filter(([, v]) => v)) };
    load(params);
  };

  const handleReset = () => {
    const reset = { supplier_id: '', warehouse_location: '', shipment_status: '', severity: '' };
    setFilters(reset);
    load({ limit });
  };

  return (
    <div className="incidents-page">
      <div className="incidents-header">
        <h2>Incident Explorer</h2>
        <p>Browse and filter all supply chain incidents in the database</p>
      </div>

      <div className="incidents-filters">
        <div className="filter-grid">
          <div className="filter-field">
            <label>Supplier ID</label>
            <input
              type="text"
              placeholder="e.g. SUP-001"
              value={filters.supplier_id}
              onChange={e => setFilters(f => ({ ...f, supplier_id: e.target.value }))}
            />
          </div>
          <div className="filter-field">
            <label>Warehouse</label>
            <input
              type="text"
              placeholder="e.g. Chicago"
              value={filters.warehouse_location}
              onChange={e => setFilters(f => ({ ...f, warehouse_location: e.target.value }))}
            />
          </div>
          <div className="filter-field">
            <label>Shipment Status</label>
            <select
              value={filters.shipment_status}
              onChange={e => setFilters(f => ({ ...f, shipment_status: e.target.value }))}
            >
              {STATUS_OPTIONS.map(s => <option key={s} value={s}>{s || 'Any'}</option>)}
            </select>
          </div>
          <div className="filter-field">
            <label>Severity</label>
            <select
              value={filters.severity}
              onChange={e => setFilters(f => ({ ...f, severity: e.target.value }))}
            >
              {SEVERITY_OPTIONS.map(s => <option key={s} value={s}>{s || 'Any'}</option>)}
            </select>
          </div>
          <div className="filter-field">
            <label>Limit</label>
            <select value={limit} onChange={e => setLimit(Number(e.target.value))}>
              {[20, 50, 100].map(n => <option key={n} value={n}>{n}</option>)}
            </select>
          </div>
        </div>
        <div className="filter-actions">
          <button className="btn-primary" onClick={handleSearch} disabled={loading}>
            {loading ? 'Loading...' : 'Apply Filters'}
          </button>
          <button className="btn-ghost" onClick={handleReset}>Reset</button>
        </div>
      </div>

      {error && (
        <div className="error-banner">Error: {error}</div>
      )}

      {data && (
        <IncidentTable
          incidents={data.incidents || []}
          title={`Incidents (${data.total ?? data.incidents?.length ?? 0} found)`}
        />
      )}
    </div>
  );
}
